      this.failures.length = 0;
      return;
    }

    if (this.currentState === "closed") {
      this.pruneFailures(this.clock());
    }
  }

  /** Records a failed completion. */
  public recordFailure(token?: string): void {
    this.advanceState();

    if (this.currentState === "half-open") {
      if (!this.matchesProbe(token)) {
        return;
      }
      this.probeToken = undefined;
      this.openAt(this.clock());
      return;
    }

    if (this.currentState !== "closed") {
      return;
    }

    const now = this.clock();
    this.pruneFailures(now);
    this.failures.push(now);
    if (this.failures.length >= this.failureThreshold) {
      this.openAt(now);
    }
  }

  public onSuccess(token?: string): void {
    this.recordSuccess(token);
  }

  public onFailure(token?: string): void {
    this.recordFailure(token);
  }

  public reset(): void {
    this.currentState = "closed";
    this.failures.length = 0;
    this.probeToken = undefined;
    this.openedAt = 0;
  }

  public snapshot(): RateCircuitBreakerSnapshot {
    this.advanceState();
    return {
      state: this.currentState,
      failureCount: this.failures.length,
      probeInFlight: this.probeToken !== undefined,
      now: this.clock(),
    };
  }

  private advanceState(): void {
    if (this.currentState === "open") {
      const now = this.clock();
      if (now - this.openedAt >= this.cooldownMs) {
        this.currentState = "half-open";
        this.probeToken = undefined;
      }
    }
  }

  private openAt(now: number): void {
    this.currentState = "open";
    this.openedAt = now;
    this.probeToken = undefined;
  }

  private pruneFailures(now: number): void {
    const cutoff = now - this.windowMs;
    while (this.failures.length > 0 && this.failures[0] <= cutoff) {
      this.failures.shift();
    }
  }

  private matchesProbe(token: string | undefined): boolean {
    if (this.probeToken === undefined) {
      return false;
    }
    return token === undefined || token === this.probeToken;
  }

  private nextToken(): string {
    this.sequence += 1;
    return `rate-circuit-${this.sequence}`;
  }
}

export function createRateCircuitBreaker(options: RateCircuitBreakerOptions): RateCircuitBreaker {
  return new RateCircuitBreaker(options);
}
"},{"path":"harness/specs/tasks/harness-gap-rate-circuit-breaker.md","content":"# L05 异常调用速率断路器

## 目标

为异常调用速率提供确定、可重放的有限状态断路器。断路器只处理速率边界，不替代 SSRF、loop guard、approval、budget 或其他既有安全检查。

## 状态机

```text
closed --达到窗口失败阈值--> open --cooldown 到期--> half-open
  ^                                      |       |
  |                                      |失败   |成功
  +--------------------------------------open   closed
```

- `closed`：滑动窗口内累计失败次数达到阈值后进入 `open`。
- `open`：cooldown 内拒绝请求；拒绝请求不得产生任何业务效果。cooldown 到期后进入 `half-open`。
- `half-open`：只放行一个探测。探测未完成时拒绝后续请求；探测成功回到 `closed`，失败回到 `open` 并重新开始 cooldown。
- 没有失败的合法速率永远不会触发断路器。

## 参数

- `failureThreshold`：窗口内触发断路器的失败次数，必须大于零。
- `windowMs`：滑动失败窗口长度，必须为非负有限数。
- `cooldownMs`：open 状态持续时间，必须为非负有限数。
- `now`：可选注入时钟，生产默认使用 `Date.now`，测试和回放必须注入确定性时钟。

## 使用约束

调用方先执行既有授权和安全检查，再调用 `tryAcquire()`。只有 `allowed === true` 时才可执行操作；`open` 或已有探测进行中的拒绝结果不得产生网络、工具或业务副作用。操作完成后使用 decision 返回的 token 调用 `recordSuccess(token)` 或 `recordFailure(token)`。

断路器不得放宽或替代：

- SSRF 防护
- tool loop detection / loop guard
- approval 流程
- 既有 budget 与调用循环保护

## 验收场景

1. 注入时钟推进，窗口内失败达到阈值后状态为 `open`。
2. open cooldown 内 `tryAcquire()` 返回拒绝，且不产生效果。
3. cooldown 到期后状态为 `half-open`，第一次探测允许，第二次拒绝。
4. 探测成功回到 closed；探测失败回到 open，且 cooldown 从失败时重新计时。
5. 纯成功流量永不 trip；滑动窗口外的旧失败会过期，不会造成后续合法窗口误断。
6. 与 tool-loop-detection 的正反回归同时通过，确保断路器不替代既有 loop guard。

## 验证

- runtime core 类型检查
- scoped lint
- harness validate / dry-run
- comms replay / compare
- 凭据扫描零命中
- SHA256SUMS 可回读
"},{"path":"docs/dev/harness-gap-closure/l05-rate-circuit-breaker.md","content":"# L05 Rate Circuit Breaker 闭环说明

## 变更

新增 `openclaw_runtime/src/agents/rate-circuit-breaker.ts`，实现由注入时钟驱动的三态断路器：

- closed 状态在滑动窗口内累计异常失败，达到配置阈值后进入 open；
- open 状态在 cooldown 内拒绝调用，拒绝调用不产生效果；
- cooldown 到期进入 half-open，只允许一个探测；
- half-open 探测成功回到 closed，失败重新进入 open 并重置 cooldown。

实现不依赖全局可变时间，测试可以通过 `now` 注入虚拟时钟并重放完整状态转换。

## 设计边界

这是异常速率边界，不是生产默认的全局熔断开关。调用方仍必须先执行 SSRF、loop guard、approval、budget 等既有检查。断路器允许或拒绝的结果不能用于放宽这些检查，也不能替代 tool-loop-detection 的正反回归。

拒绝结果必须在产生网络、工具调用或其他业务副作用之前返回。因而 `open` 状态和 half-open 探测占用期间均不得继续执行被保护操作。

