{"edits":[{"path":"openclaw_runtime/src/agents/rate-circuit-breaker.ts","content":"export type RateCircuitBreakerState = "closed" | "open" | "half-open";

export interface RateCircuitBreakerOptions {
  /** Number of failures in the sliding window that opens the circuit. */
  failureThreshold: number;
  /** Length of the sliding failure window in milliseconds. */
  windowMs: number;
  /** How long the circuit remains open before a probe is allowed. */
  cooldownMs: number;
  /** Injectable monotonic-style clock. Defaults to Date.now. */
  now?: () => number;
}

export interface RateCircuitBreakerDecision {
  allowed: boolean;
  state: RateCircuitBreakerState;
  /** Present when a request is admitted. */
  token?: string;
  reason?: "closed" | "cooldown" | "probe-in-flight" | "half-open";
}

export interface RateCircuitBreakerSnapshot {
  state: RateCircuitBreakerState;
  failureCount: number;
  probeInFlight: boolean;
  now: number;
}

interface InternalDecision extends RateCircuitBreakerDecision {
  token?: string;
}

/**
 * A finite-state circuit breaker for exceptional call rates.
 *
 * The breaker is deliberately a rate boundary: callers must not use an
 * allowed decision as a substitute for SSRF, loop, approval, budget, or other
 * authorization checks. A denied decision must be returned to the caller
 * before any effect is performed.
 */
export class RateCircuitBreaker {
  private readonly failureThreshold: number;
  private readonly windowMs: number;
  private readonly cooldownMs: number;
  private readonly clock: () => number;
  private readonly failures: number[] = [];
  private currentState: RateCircuitBreakerState = "closed";
  private openedAt = 0;
  private probeToken: string | undefined;
  private sequence = 0;

  public constructor(options: RateCircuitBreakerOptions) {
    if (!Number.isFinite(options.failureThreshold) || options.failureThreshold < 1) {
      throw new Error("failureThreshold must be a finite number greater than zero");
    }
    if (!Number.isFinite(options.windowMs) || options.windowMs < 0) {
      throw new Error("windowMs must be a finite non-negative number");
    }
    if (!Number.isFinite(options.cooldownMs) || options.cooldownMs < 0) {
      throw new Error("cooldownMs must be a finite non-negative number");
    }
    this.failureThreshold = options.failureThreshold;
    this.windowMs = options.windowMs;
    this.cooldownMs = options.cooldownMs;
    this.clock = options.now ?? Date.now;
  }

  public get state(): RateCircuitBreakerState {
    this.advanceState();
    return this.currentState;
  }

  /**
   * Attempts to admit one request. In half-open state this reserves the
   * single probe slot; concurrent callers are rejected until it completes.
   */
  public tryAcquire(): InternalDecision {
    this.advanceState();

    if (this.currentState === "open") {
      return {
        allowed: false,
        state: "open",
        reason: "cooldown",
      };
    }

    if (this.currentState === "half-open") {
      if (this.probeToken !== undefined) {
        return {
          allowed: false,
          state: "half-open",
          reason: "probe-in-flight",
        };
      }
      const token = this.nextToken();
      this.probeToken = token;
      return {
        allowed: true,
        state: "half-open",
        token,
        reason: "half-open",
      };
    }

    return {
      allowed: true,
      state: "closed",
      token: this.nextToken(),
      reason: "closed",
    };
  }

  /** Alias useful at call sites that use acquire terminology. */
  public acquire(): InternalDecision {
    return this.tryAcquire();
  }

  /**
   * Returns whether a request could be admitted. This method reserves a
   * half-open probe; use tryAcquire when the token is needed for completion.
   */
  public canRequest(): boolean {
    return this.tryAcquire().allowed;
  }

  /** Records a successful completion and closes a successful half-open probe. */
  public recordSuccess(token?: string): void {
    this.advanceState();

    if (this.currentState === "half-open") {
      if (!this.matchesProbe(token)) {
        return;
      }
      this.probeToken = undefined;
      this.currentState = "closed";
      this.failures.length = 0;
      return;
    }

    if (this.currentState === "closed") {
      this.pruneFailures(this.clock());
    }
  }

  /** Records a failed completion. */
  public recordFailure(token?: string): void {
    this.advanceState();

    if (this.currentState === "half-open") {
      if (!this.matchesProbe(token)) {
        return;
      }
      this.probeToken = undefined;
      this.openAt(this.clock());
      return;
    }

    if (this.currentState !== "closed") {
      return;
    }

    const now = this.clock();
    this.pruneFailures(now);
    this.failures.push(now);
    if (this.failures.length >= this.failureThreshold) {
      this.openAt(now);
    }
  }

  public onSuccess(token?: string): void {
    this.recordSuccess(token);
  }

  public onFailure(token?: string): void {
    this.recordFailure(token);
  }

  public reset(): void {
    this.currentState = "closed";
    this.failures.length = 0;
    this.probeToken = undefined;
    this.openedAt = 0;
  }

  public snapshot(): RateCircuitBreakerSnapshot {
    this.advanceState();
    return {
      state: this.currentState,
      failureCount: this.failures.length,
      probeInFlight: this.probeToken !== undefined,
      now: this.clock(),
    };
  }

  private advanceState(): void {
    if (this.currentState === "open") {
      const now = this.clock();
      if (now - this.openedAt >= this.cooldownMs) {
        this.currentState = "half-open";
        this.probeToken = undefined;
      }
    }
  }

  private openAt(now: number): void {
    this.currentState = "open";
    this.openedAt = now;
    this.probeToken = undefined;
  }

  private pruneFailures(now: number): void {
    const cutoff = now - this.windowMs;
    while (this.failures.length > 0 && this.failures[0] <= cutoff) {
      this.failures.shift();
    }
  }

  private matchesProbe(token: string | undefined): boolean {
    if (this.probeToken === undefined) {
      return false;
    }
    return token === undefined || token === this.probeToken;
  }

  private nextToken(): string {
    this.sequence += 1;
    return `rate-circuit-${this.sequence}`;
  }
}

export function createRateCircuitBreaker(options: RateCircuitBreakerOptions): RateCircuitBreaker {
  return new RateCircuitBreaker(options);
}
