  public tryAcquire(): InternalDecision {
    this.advanceState();

    if (this.currentState === "open") {
      return {
        allowed: false,
        state: "open",
        reason: "cooldown",
      };
    }

    if (this.currentState === "half-open") {
      if (this.probeToken !== undefined) {
        return {
          allowed: false,
          state: "half-open",
          reason: "probe-in-flight",
        };
      }
      const token = this.nextToken();
      this.probeToken = token;
      return {
        allowed: true,
        state: "half-open",
        token,
        reason: "half-open",
      };
    }

    return {
      allowed: true,
      state: "closed",
      token: this.nextToken(),
      reason: "closed",
    };
  }

