   * Returns whether a request could be admitted. This method reserves a
   * half-open probe; use tryAcquire when the token is needed for completion.
   */
  public canRequest(): boolean {
    return this.tryAcquire().allowed;
  }

  /** Records a successful completion and closes a successful half-open probe. */
  public recordSuccess(token?: string): void {
    this.advanceState();

    if (this.currentState === "half-open") {
      if (!this.matchesProbe(token)) {
        return;
      }
      this.probeToken = undefined;
      this.currentState = "closed";
      this.failures.length = 0;
      return;
    }

    if (this.currentState === "closed") {
      this.pruneFailures(this.clock());
    }
  }

